$ErrorActionPreference = 'Stop'
$case = 'C:\Users\kt66student\Documents\book2-ch07-20261103-173702'
$expectedParent = 'C:\Users\kt66student\Documents'
$resolved = (Resolve-Path -LiteralPath $case).Path
if ($resolved -cne $case -or [System.IO.Path]::GetDirectoryName($resolved) -cne $expectedParent) { throw 'Unexpected cleanup path' }
$expected = @{
 'Security.evtx'='3E6FAD82C33E3F58B60B5275A6058C595C6300CDB2FCFB1477DD4D6BF0E1AEB8'
 'System.evtx'='19ECD6BE80E639BADE6713B6B18396703FC9C8DCE94AE28D88E47B30936013C4'
 'Defender.evtx'='8DE2ACD48013E0EBBCE9EFCBDB06C76621DD4833E9C111CC6F10E820D4E96046'
}
$items = @(Get-ChildItem -LiteralPath $case -Force)
if ($items.Count -ne 3) { throw 'Unexpected directory contents' }
$verified = foreach ($item in $items) {
 if ($item.PSIsContainer -or -not $expected.ContainsKey($item.Name)) { throw 'Unexpected item' }
 $hash = (Get-FileHash -LiteralPath $item.FullName -Algorithm SHA256).Hash
 if ($hash -ne $expected[$item.Name]) { throw 'Export changed since creation' }
 [pscustomobject]@{Path=$item.FullName;SHA256=$hash}
}
foreach ($item in $items) { Remove-Item -LiteralPath $item.FullName }
if (@(Get-ChildItem -LiteralPath $case -Force).Count -ne 0) { throw 'Folder not empty' }
[System.IO.Directory]::Delete($case, $false)
$status = Get-MpComputerStatus
[pscustomobject]@{
 VerifiedExports=$verified
 ExportFolderExists=(Test-Path -LiteralPath $case)
 Services=@(Get-Service EventLog,WazuhSvc,WinDefend,Sysmon64 | Select-Object Name,@{n='Status';e={$_.Status.ToString()}})
 RealTimeProtectionEnabled=$status.RealTimeProtectionEnabled
 IsTamperProtected=$status.IsTamperProtected
} | ConvertTo-Json -Depth 5
